    console.print(Markdown(text))

def countdown(seconds: int, message: str = "Retrying", cancel_check=None) -> bool:
    """Live countdown on a single line. Returns True if cancelled via *cancel_check*."""
    with Live(
        Text(f"{message} in {seconds}s ...", style="dim"), console=console, refresh_per_second=2, transient=True
    ) as live:
        for remaining in range(seconds, 0, -1):
            if cancel_check and cancel_check():
                return True
            live.update(Text(f"{message} in {remaining}s ...", style="dim"))
            time.sleep(1)
    return False

def code_block(code: str, lang: str = "python") -> None:
    syntax = Syntax(code, lang, theme="monokai", line_numbers=True, word_wrap=True)
    console.print(Panel(syntax, title="[exec]EXEC[/exec]", border_style="yellow", padding=(0, 0)))

def output_panel(text: str) -> None:
    console.print(Panel(escape(text), title="[output]OUTPUT[/output]", border_style="dim", padding=(0, 1)))

def rule(title: str = "", style: str = "dim") -> None:
    console.print(Rule(title=title, style=style))

def log_exception() -> None:
    """Plain traceback to the log file only — nothing on terminal."""
    if _file_logger:
        _file_logger.error(traceback.format_exc())

def spinner(message: str = "Working..."):
    """Returns a rich Status context manager for use with `with` blocks."""
    return console.status(f"[dim]{message}[/dim]", spinner="aesthetic", spinner_style="cyan")

_active_listener = None

class CLIListener:
    """Wrapper around threading.Event to cleanly stop/pause the listener thread and restore terminal."""

    def __init__(
        self,
        active_event: threading.Event,
        thread: threading.Thread,
        paused_event: threading.Event,
        paused_ack_event: threading.Event,
    ):
        self._active_event = active_event
        self._thread = thread
        self._paused_event = paused_event
        self._paused_ack_event = paused_ack_event

    def pause(self) -> None:
        if self._thread and self._thread.is_alive():
            self._paused_event.set()
            self._paused_ack_event.wait(timeout=1.0)

    def resume(self) -> None:
        self._paused_event.clear()

    def clear(self) -> None:
        global _active_listener
        if _active_listener is self:
            _active_listener = None
        self._active_event.clear()
        self._paused_event.clear()
        if self._thread and self._thread.is_alive():
            self._thread.join(timeout=0.5)

    def is_set(self) -> bool:
        return self._active_event.is_set()

    def __bool__(self) -> bool:
        return True

def get_prompt_toolkit_bindings():
    kb = KeyBindings()

    # Alt+Enter (escape, enter) or Ctrl+Enter/Ctrl+J (c-j) inserts a newline
    @kb.add("escape", "enter")
    @kb.add("c-j")
    def _(event):
        event.current_buffer.insert_text("\n")

    # Normal Enter submits the entire buffer
    @kb.add("enter")
    def _(event):
        event.current_buffer.validate_and_handle()

    return kb

def prompt_continuation(width, line_number, is_soft_wrap):
    return "." * (width - 1) + " "

def _pt_prompt(message: str, *, multiline: bool = False, validator=None, default: str = "") -> str:
    global _active_listener
    if _active_listener:
        _active_listener.pause()
    try:
        time.sleep(0.1)
        if HAS_PT:
            kwargs = {"multiline": multiline, "default": default}
            if multiline:
                kwargs["prompt_continuation"] = prompt_continuation
                kwargs["key_bindings"] = get_prompt_toolkit_bindings()
            if validator is not None:
                kwargs["validator"] = validator
                kwargs["validate_while_typing"] = False
            return pt_prompt(HTML(f"<ansicyan><bold>{message}</bold></ansicyan>"), **kwargs).strip()
        if os.name != "nt":
            return input(f"[1;36m{message}[0m").strip()
        return console.input(f"[bold cyan]{message}[/bold cyan]").strip()
    except (KeyboardInterrupt, EOFError):
        raise
    finally:
        if _active_listener:
            _active_listener.resume()

def _build_session_name_validator():
    if not HAS_PT or Validator is None:
        return None

    class _SessionNameValidator(Validator):
        def validate(self, document):
            text = document.text.strip()
            if not text:
                return
            banned = set(r'<>:"/\|?*')
            bad = next((ch for ch in text if ch in banned), None)
            if bad is not None:
                raise ValidationError(
                    message=f"Session name cannot contain '{bad}'",
                    cursor_position=document.cursor_position,
                )
            if text in {".", ".."}:
                raise ValidationError(
                    message="Session name cannot be '.' or '..'",
                    cursor_position=document.cursor_position,
                )

    return _SessionNameValidator()

def prompt_yes_no(message: str, *, default: bool = True) -> bool:
    suffix = "[Y/n]" if default else "[y/N]"
    while True:
        answer = _pt_prompt(f"{message} {suffix} ").lower()
        if not answer:
            return default
        if answer in {"y", "yes"}:
            return True
        if answer in {"n", "no"}:
            return False
        warn("Please enter y or n.")

def prompt() -> str:
    global _active_listener
    if _active_listener:
        _active_listener.pause()
    try:
        # Give asynchronous Rich spinners time to fully exit and clear lines
        time.sleep(0.1)
        if HAS_PT:
            return pt_prompt(
                HTML("<ansigreen><bold>&gt;&gt;&gt; </bold></ansigreen>"),
                multiline=True,
                prompt_continuation=prompt_continuation,
                key_bindings=get_prompt_toolkit_bindings(),
            )
        else:
            if os.name != "nt":
                return input("\x01\033[1;32m\x02>>> \x01\033[0m\x02")
            else:
                return console.input("[bold green]>>> [/bold green]")
    finally:
        if _active_listener:
            _active_listener.resume()

def ask_session_name() -> str:
    global _active_listener
    if _active_listener:
        _active_listener.pause()
    try:
        # Give asynchronous Rich spinners time to fully exit and clear lines
        time.sleep(0.1)
        if HAS_PT:
            return pt_prompt(
                HTML(
                    "<ansicyan><bold>Enter a name for this recording session "
                    "(leave blank to auto-detect domain): </bold></ansicyan>"
                )
            ).strip()
        else:
            if os.name != "nt":
                p = (
                    "\x01\033[1;36m\x02Enter a name for this recording session "
                    "(leave blank to auto-detect domain): \x01\033[0m\x02"
                )
                return input(p).strip()
            else:
                msg = (
                    "[bold cyan]Enter a name for this recording session "
                    "(leave blank to auto-detect domain): [/bold cyan]"
                )
                return console.input(msg).strip()
    finally:
        if _active_listener:
            _active_listener.resume()

def ask_resume_session(dirs: list | None = None, sessions: list | None = None) -> Path | None:
    """Interactively pick a session to resume.

    Always shows a numbered picker of available sessions.
    Enter selects the first (latest) session, or type a number/index.
    If *dirs* is provided, only those sessions are shown.
    If *sessions* is provided, use them instead of scanning HISTORY_DIR
    (avoids re-scanning when the preload thread already did it).
    Returns the selected history_dir Path, or None if cancelled.
    """
    from ..core.history import list_resumable_sessions

    global _active_listener

    def _pause():
        if _active_listener:
            _active_listener.pause()

    def _resume():
        if _active_listener:
            _active_listener.resume()

    def _do_prompt(message: str) -> str:
        _pause()
        try:
            time.sleep(0.1)
            if HAS_PT:
                return pt_prompt(HTML(f"<ansicyan><bold>{message}</bold></ansicyan>")).strip()
            elif os.name != "nt":
                return input(f"\x01\033[1;36m\x02{message}\x01\033[0m\x02").strip()
            else:
                return console.input(f"[bold cyan]{message}[/bold cyan]").strip()
        finally:
            _resume()

    # ── Gather sessions to display ──────────────────────────────────────────
    all_sessions = sessions if sessions is not None else list_resumable_sessions()
    if not all_sessions:
        error("No resumable sessions found.")
        return None

    if dirs is not None:
        sessions = [s for s in all_sessions if s.history_dir in dirs]
        if not sessions:
            error("No matching sessions found.")
            return None
    else:
        sessions = all_sessions

    # ── Show numbered picker ─────────────────────────────────────────────────
    console.print()
    t = Table(show_header=False, box=None, collapse_padding=True, padding=(0, 1))
    t.add_column(style="bold cyan", width=5)
    t.add_column(style="bold", min_width=20)
    t.add_column(style="dim")
    for i, s in enumerate(sessions, 1):
        marker = " (latest)" if i == 1 else ""
        t.add_row(f"{i}.", f"{s.recording_name}{marker}", s.human_timestamp)
    console.print(t)
    console.print()

    choice = _do_prompt("Select session [1]: ")
    if not choice:
        idx = 1
    else:
        try:
            idx = int(choice)
        except ValueError:
            # Try matching by name text
            filtered = [s for s in sessions if choice in s.recording_name or choice in s.folder_name]
            if len(filtered) == 1:
                return filtered[0].history_dir
            if not filtered:
                error(f"No sessions matching '{choice}'.")
                return None
            # Multiple name matches — show sub-picker
            sessions = filtered
            console.print()
            t2 = Table(show_header=False, box=None, collapse_padding=True, padding=(0, 1))
            t2.add_column(style="bold cyan", width=5)
            t2.add_column(style="bold", min_width=20)
            t2.add_column(style="dim")
            for i, s in enumerate(sessions, 1):
                t2.add_row(f"{i}.", s.recording_name, s.human_timestamp)
            console.print(t2)
            console.print()
            choice = _do_prompt("Select [1]: ")
            if not choice:
                idx = 1
            else:
                try:
                    idx = int(choice)
                except ValueError:
                    error(f"Invalid selection: {choice}")
                    return None

    if 1 <= idx <= len(sessions):
        return sessions[idx - 1].history_dir
    error(f"Selection out of range: {idx}")
    return None

def _track_force_quit() -> None:
    """Fire a force-quit telemetry event and flush before os._exit kills the process."""
    try:
        from automatiq.core.telemetry import SystemCrashProps, client

        client.track_system_crash(
            SystemCrashProps(
                crash_type="force_quit",
                exception_class=None,
                module=None,
                active_command=client.active_command,
            )
        )
        client.stop()
    except Exception:
        pass

def start_cli_listeners(cancel_token: CancelToken, stop_token: StopToken, on_force_quit=None) -> CLIListener | None:
    if not sys.stdin.isatty():
        return None

    active = threading.Event()
    active.set()
    paused = threading.Event()
    paused_ack = threading.Event()

    # Catch raw OS SIGINT to prevent KeyboardInterrupt from crashing the main thread on the first press
    try:

        def sigint_handler(signum, frame):
            if stop_token.is_stopped():
                # Second press: Force a hard exit
                print("\n[ERROR] Force quit requested (Double Ctrl+C). Shutting down immediately.")
                if on_force_quit:
                    try:
                        on_force_quit()
                    except Exception:
                        pass
                _track_force_quit()
                os._exit(1)
            else:
                stop_token.stop()

        signal.signal(signal.SIGINT, sigint_handler)
    except (ValueError, OSError):
        pass  # Fails gracefully if not running in the main thread

    def _listen():
        try:
            from prompt_toolkit.input import create_input
            from prompt_toolkit.keys import Keys

            inp = create_input()
        except Exception:
            return  # Fallback gracefully if prompt_toolkit fails to initialize

        while active.is_set():
            if paused.is_set():
                paused_ack.set()
                while paused.is_set() and active.is_set():
                    time.sleep(0.05)
                if active.is_set():
                    paused_ack.clear()

            if not active.is_set():
                break

            try:
                # Enter raw mode only while actively listening
                with inp.raw_mode():
                    while active.is_set() and not paused.is_set():
                        keys = inp.read_keys()
                        for k in keys:
                            if k.key == Keys.Escape:
                                cancel_token.cancel()
                            elif k.key == Keys.ControlC:
                                if stop_token.is_stopped():
                                    print("\n[ERROR] Force quit requested (Double Ctrl+C). Shutting down immediately.")
                                    if on_force_quit:
                                        try:
                                            on_force_quit()
                                        except Exception:
                                            pass
                                    _track_force_quit()
                                    os._exit(1)
                                else:
                                    stop_token.stop()
                        time.sleep(0.05)
            except Exception:
                time.sleep(0.05)

    t = threading.Thread(target=_listen, daemon=True)
    t.start()
    global _active_listener
    _active_listener = CLIListener(active, t, paused, paused_ack)
    return _active_listener

# ---------------------------------------------------------------------------
# Global Event Listeners for UI updates
# ---------------------------------------------------------------------------

@events.log_info.connect
def handle_log_info(sender, text, **kwargs):
    if text.startswith("[ACTION]"):
        action(text.replace("[ACTION]", "", 1).strip())
    elif text.startswith("[VIDEO]"):
        video(text.replace("[VIDEO]", "", 1).strip())
    elif text.startswith("[AI]"):
        ai(text.replace("[AI]", "", 1).strip())
    else:
        info(text)

@events.log_debug.connect
def handle_log_debug(sender, text, **kwargs):
    debug(text)

@events.log_warn.connect
def handle_log_warn(sender, text, **kwargs):
    warn(text)

@events.log_error.connect
def handle_log_error(sender, text, **kwargs):
    error(text)

@events.log_traceback.connect
def handle_log_traceback(sender, **kwargs):
    log_exception()

import queue import threading import time
from rich.console import Group from rich.live import Live from rich.markdown import Markdown from rich.panel import Panel from rich.progress import BarColumn, Progress, TaskProgressColumn, TextColumn from rich.spinner import Spinner from rich.text import Text
from ..core import events from ..core.cancel_standard import CancelToken, StopToken from ..core.main import run_agent from .console import ( agent_markdown, code_block, console, countdown, error, info, log_exception, output_panel, prompt, think, )
# Global state _active_live = None _first_prompt = True
# Persistent spinners — reused across refresh ticks so they actually animate. # A fresh Spinner() each tick always shows frame 0 because start_time resets. _think_spinner = Spinner("aesthetic", text="Thinking... (Press Esc to Stop)", style="cyan") _run_spinner = Spinner("aesthetic", text="Running... (Press Esc to Stop)", style="cyan")
# Streaming state _thought_buf: list[str] = [] _text_buf: list[str] = [] _total_generation_time = 0.0 _generation_start = 0.0 _session_tokens = 0
# Restore progress _restore_progress = Progress( TextColumn("[bold cyan]Restoring cells"), BarColumn(), TaskProgressColumn(), TextColumn("{task.completed}/{task.total}"), transient=False, ) _restore_task_id = None
# Phase: "streaming" (Live shows streamed content) | "tool_exec" (Live shows the run spinner). # Live is stopped explicitly between phases. _phase = "streaming"
# ── Streaming render helpers ────────────────────────────────────────────────
def _split_md_pending(buffer: str): """Split buffer at last newline.
Returns ``(markdown_renderable, pending_text)``: - completed lines → :class:`Markdown` (re-parsed only on newline boundary) - in-progress line → :class:`Text` with a cursor block char ``▍`` """ if not buffer: return None, None idx = buffer.rfind("\n") if idx == -1: return None, Text(buffer + "\u258d", style="dim") completed = buffer[: idx + 1] pending = buffer[idx + 1 :] md = Markdown(completed) if completed.strip() else None pt = Text(pending + "\u258d", style="dim") if pending else None return md, pt
def _build_stream_group(): """Build the streaming render group: content + spinner + status line.""" thought_full = "".join(_thought_buf) text_full = "".join(_text_buf)
# Thought panel thought_parts = [] if thought_full: md, pt = _split_md_pending(thought_full) if md: thought_parts.append(md) if pt: thought_parts.append(pt)
thought_panel = None if thought_parts: inner = thought_parts[0] if len(thought_parts) == 1 else Group(*thought_parts) thought_panel = Panel( inner, title="[think]Thinking[/think]", border_style="dim", padding=(0, 1), )
# Text area (below thought panel, no panel) text_parts = [] if text_full: md, pt = _split_md_pending(text_full) if md: text_parts.append(md) if pt: text_parts.append(pt)
content_children = [p for p in [thought_panel] if p is not None] + text_parts content_area = Group(*content_children) if content_children else Text("")
# Status line — only counts time while the model is generating if _generation_start: elapsed = int(_total_generation_time + (time.monotonic() - _generation_start)) else: elapsed = int(_total_generation_time) status = Text( f"elapsed: {elapsed}s | session: {_session_tokens:,} tokens", style="dim", )
return Group(content_area, _think_spinner, status)
def _get_renderable(): """Return the current Live renderable based on phase.
Called by Live's auto-refresh thread (10x/sec) under the Live's lock. The Live is only active during 'streaming' and 'tool_exec' phases. """ if _phase == "streaming": return _build_stream_group() if _restore_task_id is not None: return _restore_progress return _run_spinner
def _start_live(): """Start the persistent Live region if not already running.""" global _active_live if _active_live is None: _active_live = Live( get_renderable=_get_renderable, console=console, refresh_per_second=10, transient=True, redirect_stdout=False, redirect_stderr=False, ) _active_live.__enter__()
def _stop_live(): """Stop the active Live region if one exists.""" global _active_live if _active_live is not None: _active_live.__exit__(None, None, None) _active_live = None
