Called after the Live has been stopped (transient=True clears the streaming display), so this content appears cleanly in the scrollback with no cursor repositioning or flicker. """ global _thought_buf, _text_buf thought_full = "".join(_thought_buf) text_full = "".join(_text_buf) if thought_full.strip(): think(thought_full) if text_full.strip(): agent_markdown(text_full) _thought_buf = [] _text_buf = []
