      """CancelToken standard — thread-safe cancellation flag for long-running tasks.

This module provides a single, unified cancellation primitive used across
the agent loop, sandbox execution, and workspace compilation.  It replaces
all OS-level Esc-key polling that previously read raw bytes from stdin.
"""

import threading

class StopToken:
    """A thread-safe stop flag passed to completely abort operations (e.g. via Ctrl+C)."""

    def __init__(self):
        self._event = threading.Event()

    def stop(self):
        """Set the stop flag."""
        self._event.set()

    def reset(self):
        """Clear the stop flag."""
        self._event.clear()

    def is_stopped(self) -> bool:
        """Check if stop was requested."""
        return self._event.is_set()

class StopRequestedException(Exception):
    """Raised when an operation is completely aborted via StopToken."""

    pass

class CancelToken:
    """A thread-safe cancellation flag passed to long-running tasks."""

    def __init__(self):
        self._event = threading.Event()

    def cancel(self):
        """Set the cancel flag."""
        self._event.set()

    def reset(self):
        """Clear the cancel flag."""
        self._event.clear()

    def is_cancelled(self) -> bool:
        """Check if cancellation was requested."""
        return self._event.is_set()

class CancelRequestedException(Exception):
    """Raised when an operation is aborted via CancelToken."""

    pass

def run_cancellable(token: CancelToken, func, *args, stop_token: StopToken = None, **kwargs):
    """Run a function in a background thread, raising if cancelled or stopped.

    Raises :class:`CancelRequestedException` if *token* is cancelled (and resets it
    before raising), or :class:`StopRequestedException` if *stop_token* is stopped.
    """
    if token and token.is_cancelled():
        token.reset()
        raise CancelRequestedException()

    result = []
    error = []
    done = threading.Event()

    def _worker():
        try:
            result.append(func(*args, **kwargs))
        except Exception as e:
            error.append(e)
        finally:
            done.set()

    thread = threading.Thread(target=_worker, daemon=True)
    thread.start()

    while not done.wait(timeout=0.15):
        if token and token.is_cancelled():
            token.reset()
            raise CancelRequestedException("Cancelled via token")
        if stop_token and stop_token.is_stopped():
            raise StopRequestedException("Aborted via stop token")

    if error:
        raise error[0]
    return result[0]

      def check_duplicate_thought(current_description: str, prev_description: str) -> str | None:
    """Check if the agent is submitting the exact same description for an action."""
    if current_description == prev_description and current_description:
        return (
            "SYSTEM: You have submitted the exact same description as the previous turn — "
            "word for word. You are looping. Either:\n"
            "1. Switch to a different mode for a fresh perspective, or\n"
            "2. Tell the user what you've found so far and ask for guidance.\n"
            "Do NOT repeat the same action."
        )
    return None

def check_repeated_execution(script_to_run: str, exec_history: list[tuple[str, str, int]]) -> tuple[bool, str | None]:
    """Check if the exact same script has been executed multiple times."""
    repeat_count = 0
    matched_cell = None

    script_to_run = script_to_run.strip()
    for prev_script, _prev_output, prev_cell in exec_history:
        if script_to_run == prev_script:
            repeat_count += 1
            matched_cell = prev_cell

    if repeat_count >= 2 and matched_cell is not None:
        warning = (
            f"SYSTEM: This exact script has already been executed {repeat_count} times "
            f"with the same output. It was NOT executed again. "
            f"Use %view_output Cell_{matched_cell} to review the previous output. "
            f"Try a fundamentally different approach."
        )
        return True, warning

    return False, None

def check_final_script_bounce(current_mode: str, final_script_bounces: int, max_bounces: int) -> tuple[bool, str | None]:
    """Handle final script submission constraints."""
    if current_mode != "building":
        return True, (
            "SYSTEM: Final script submitted outside building mode. "
            "Switch to reading or testing mode before attempting to finalise. "
            "Rule: only submit the final script when in building mode."
        )

    # Note: final_script_bounces has already been incremented before this check in main loop
    if final_script_bounces < max_bounces:
        return True, (
            "SYSTEM: Final script received but not yet verified. "
            "Confirm you have tested it in testing mode. "
            "If reading/testing mode cannot produce a working solution, "
            "inform the user in plain text and halt. "
            "Otherwise, resubmit once testing is complete."
        )

    return False, None

      import json
import logging

import litellm

from . import config

logger = logging.getLogger(__name__)

def extract_message(exc) -> str:
    """Pull a readable summary from an exception, stripping litellm wrapper noise."""
    import re

    def _clean(raw):
        s = str(raw)
        s = re.sub(r"^(?:[\w\.]+:\s*)+", "", s)
        s = re.sub(r"^\w+Exception\s+\w+\s*-\s*", "", s)
        json_match = re.search(r"\{.*\}", s, re.DOTALL)
        if json_match:
            try:
                body = json.loads(json_match.group())
                if "error" in body:
                    err = body["error"]
                    if isinstance(err, dict) and "message" in err:
                        return err["message"]
                    return str(err)
                if "message" in body:
                    return body["message"]
            except json.JSONDecodeError:
                pass
        return s.split("\n")[0][:300]

    return _clean(exc)

def _build_model_help(model: str, original_msg: str) -> str:
    """Build a simple error message for an invalid or unsupported model."""
    if "/" not in model:
        return (
            f"Invalid model string '{model}'. Expected format: 'provider/model-name' "
            f"(e.g. 'gemini/gemini-2.5-flash').\n"
            f"Original error: {original_msg}"
        )

    return (
        f"The requested model '{model}' either does not exist, is not supported by the provider, "
        f"or there is a problem on their server side.\n"
        f"Original error: {original_msg}"
    )

def _is_model_error(exc: Exception) -> bool:
    msg = extract_message(exc).lower()
    needles = [
        "llm provider not provided",
        "unable to map your input to a model",
        "invalid model",
        "model not found",
        "unknown model",
        "unsupported model",
        "model is not supported",
    ]
    return any(n in msg for n in needles)

def call_llm_streaming(msgs: list[dict], tools: list[dict]):
    """Streaming LLM call to litellm.

    Yields tuples of ``(reasoning_delta, content_delta, tool_call_deltas, usage)``:

    - ``reasoning_delta`` — ``str | None`` fragment of reasoning/thinking content
    - ``content_delta`` — ``str | None`` fragment of response content
    - ``tool_call_deltas`` — ``list[dict] | None`` of tool-call delta dicts,
      each with keys ``index``, ``id``, ``name``, ``arguments``.  The first
      chunk for a given index carries ``id`` and ``name``; subsequent chunks
      carry only ``arguments`` JSON fragments to concatenate.
    - ``usage`` — litellm ``Usage`` object or ``None``; only present on the
      final chunk (when ``stream_options={"include_usage": True}`` is honored).
    """
    kwargs = dict(
        model=config.AGENT_MODEL,
        messages=msgs,
        tools=tools,
        tool_choice="auto",
        temperature=0.3,
        stream=True,
        stream_options={"include_usage": True},
    )
    if config.API_BASE:
        kwargs["api_base"] = config.API_BASE

    if litellm.supports_reasoning(model=config.AGENT_MODEL):
        kwargs["reasoning_effort"] = "high"

    try:
        response = litellm.completion(**kwargs)
        for chunk in response:
            # Usage-only chunk (choices is empty on the trailing usage chunk)
            if not chunk.choices:
                u = getattr(chunk, "usage", None)
                if u is not None:
                    yield (None, None, None, u)
                continue

            delta = chunk.choices[0].delta
            content_delta = getattr(delta, "content", None)
            reasoning_delta = getattr(delta, "reasoning_content", None)
            raw_tool_calls = getattr(delta, "tool_calls", None)
            u = getattr(chunk, "usage", None)

            tc_list: list[dict] | None = None
            if raw_tool_calls:
                tc_list = []
                for tc in raw_tool_calls:
                    func = getattr(tc, "function", None)
                    tc_list.append(
                        {
                            "index": tc.index,
                            "id": getattr(tc, "id", None),
                            "name": getattr(func, "name", None) if func else None,
                            "arguments": getattr(func, "arguments", "") if func else "",
                        }
                    )

            yield (reasoning_delta, content_delta, tc_list, u)
    except Exception as exc:
        if _is_model_error(exc):
            raise ValueError(_build_model_help(config.AGENT_MODEL, extract_message(exc))) from exc
        raise

      """Tool Definition and Validation"""

# ruff: noqa: E501

def validate_ipython_script(code: str) -> str:
    """Validate IPython script syntax using IPython's native TransformerManager."""
    stripped = code.strip()
    if not stripped:
        raise ValueError("Script cannot be empty.")

    # Sandbox-handled magics bypass IPython's transformer
    if any(stripped.startswith(m) for m in ("%reset", "%restore", "%view_output")):
        return code

    from IPython.core.inputtransformer2 import TransformerManager

    tm = TransformerManager()
    status, _ = tm.check_complete(code + "\n")

    if status == "invalid":
        raise ValueError("Syntax error: the IPython code is invalid.")
    if status == "incomplete":
        raise ValueError("Incomplete code: the cell expects more lines (unclosed block, bracket, or string).")

    # check_complete passed — compile the transformed Python to catch deeper errors
    try:
        compile(tm.transform_cell(code), "<cell>", "exec")
    except SyntaxError as e:
        raise ValueError(f"Syntax error: {e.msg} at line {e.lineno}") from e

    return code

def validate_tool_args(tool_name: str, tool_args: dict) -> str | None:
    """Validate tool arguments and return an error message if invalid."""
    if tool_name == "execute_ipython":
        if "ipython_script" not in tool_args or not isinstance(tool_args["ipython_script"], str):
            return "Missing or invalid 'ipython_script' string."

        try:
            validate_ipython_script(tool_args["ipython_script"])
        except ValueError as e:
            return str(e)

        if "description" not in tool_args or not isinstance(tool_args["description"], str):
            return "Missing 'description' string. Provide a 5-10 word description."

    elif tool_name == "switch_mode":
        valid_modes = ["reading", "testing", "building"]
        if "target_mode" not in tool_args or tool_args["target_mode"] not in valid_modes:
            return "Missing or invalid 'target_mode'. Must be reading, testing, or building."
        elif "context" not in tool_args or not isinstance(tool_args["context"], str):
            return "Missing or invalid 'context' string."

    elif tool_name == "final_submit":
        if "final_python_script" not in tool_args or not isinstance(tool_args["final_python_script"], str):
            return "Missing or invalid 'final_python_script' string."

    else:
        return f"Unknown tool name: {tool_name}"

    return None

