      import sqlite3
import time
from collections import OrderedDict
from pathlib import Path
from urllib.parse import urlparse

from .. import events

class LRUCache:
    """Simple LRU cache backed by an OrderedDict."""

    __slots__ = ("_capacity", "_data")

    def __init__(self, capacity: int = 4096):
        self._capacity = capacity
        self._data: OrderedDict[str, bool] = OrderedDict()

    def get(self, key: str) -> bool | None:
        if key in self._data:
            self._data.move_to_end(key)
            return self._data[key]
        return None

    def put(self, key: str, value: bool) -> None:
        if key in self._data:
            self._data.move_to_end(key)
        else:
            if len(self._data) >= self._capacity:
                self._data.popitem(last=False)
        self._data[key] = value

    def clear(self) -> None:
        self._data.clear()

def _reverse_domain(domain: str) -> str:
    """Reverse a domain for prefix-based subdomain matching.

    Example: 'ads.google.com' -> 'com.google.ads'
    """
    return ".".join(reversed(domain.lower().strip(".").split(".")))

def _extract_domain(url: str) -> str:
    """Pull the hostname out of a URL, lowercased."""
    try:
        return (urlparse(url).hostname or "").lower()
    except Exception:
        return ""

class BlocklistDB:
    """SQLite-backed domain blocklist with reversed-domain indexing and LRU cache."""

    def __init__(self, db_path: str = ":memory:", cache_size: int = 4096):
        self.db_path = db_path
        self._conn: sqlite3.Connection | None = None
        self._cache = LRUCache(cache_size)
        try:
            self._conn = sqlite3.connect(db_path, check_same_thread=False)
            self._conn.execute("PRAGMA journal_mode=WAL")
            self._conn.execute("PRAGMA synchronous=NORMAL")
            self._init_schema()
        except sqlite3.Error as exc:
            events.log_error.send("recorder", text=f"Failed to open/initialise blocklist DB at {db_path}: {exc}")
            events.log_traceback.send("recorder")
            raise

    def _init_schema(self) -> None:
        try:
            cur = self._conn.cursor()
            cur.executescript("""
                CREATE TABLE IF NOT EXISTS sources (
                    name        TEXT PRIMARY KEY,
                    url         TEXT,
                    enabled     INTEGER DEFAULT 1,
                    loaded_at   REAL,
                    domain_count INTEGER DEFAULT 0
                );

                CREATE TABLE IF NOT EXISTS domains (
                    reversed_domain TEXT NOT NULL,
                    source          TEXT NOT NULL,
                    added_at        REAL NOT NULL,
                    FOREIGN KEY (source) REFERENCES sources(name)
                );

                CREATE INDEX IF NOT EXISTS idx_domains_reversed
                    ON domains(reversed_domain);

                CREATE INDEX IF NOT EXISTS idx_domains_source
                    ON domains(source);
            """)
            self._conn.commit()
        except sqlite3.Error as exc:
            events.log_error.send("recorder", text=f"Failed to create blocklist schema: {exc}")
            events.log_traceback.send("recorder")
            raise

    # ── List management ──────────────────────────────────────────────

    def load_file(self, path: str, source_name: str | None = None, source_url: str | None = None) -> int:
        """Parse a hosts/domain-list file and bulk-insert into the DB."""
        source_name = source_name or Path(path).stem
        now = time.time()
        domains = []

        try:
            fh = open(path, encoding="utf-8", errors="replace")
        except OSError as exc:
            events.log_error.send("recorder", text=f"Cannot open blocklist file {path}: {exc}")
            events.log_traceback.send("recorder")
            return 0

        with fh as f:
            for line in f:
                line = line.strip()
                if not line or line[0] in ("#", "!", "/"):
                    continue

                parts = line.split()

                if len(parts) >= 2 and parts[0] in ("0.0.0.0", "127.0.0.1"):
                    domain = parts[1].lower()
                elif len(parts) == 1:
                    domain = parts[0].lower()
                else:
                    continue

                if "." not in domain or domain in ("0.0.0.0", "localhost", "localhost.localdomain"):
                    continue

                domains.append((_reverse_domain(domain), source_name, now))

        if not domains:
            return 0

        try:
            cur = self._conn.cursor()

            cur.execute("DELETE FROM domains WHERE source = ?", (source_name,))

            cur.executemany("INSERT INTO domains (reversed_domain, source, added_at) VALUES (?, ?, ?)", domains)

            cur.execute(
                """
                INSERT INTO sources (name, url, enabled, loaded_at, domain_count)
                VALUES (?, ?, 1, ?, ?)
                ON CONFLICT(name) DO UPDATE SET
                    url = excluded.url,
                    loaded_at = excluded.loaded_at,
                    domain_count = excluded.domain_count
            """,
                (source_name, source_url or path, now, len(domains)),
            )

            self._conn.commit()
            self._cache.clear()
            return len(domains)
        except sqlite3.Error as exc:
            events.log_error.send("recorder", text=f"Failed to load blocklist source '{source_name}': {exc}")
            events.log_traceback.send("recorder")
            return 0

    def list_sources(self) -> list[dict]:
        """Return metadata for all loaded sources."""
        cur = self._conn.execute("SELECT name, url, enabled, loaded_at, domain_count FROM sources ORDER BY name")
        return [
            {"name": r[0], "url": r[1], "enabled": bool(r[2]), "loaded_at": r[3], "domain_count": r[4]}
            for r in cur.fetchall()
        ]

    # ── Lookup ───────────────────────────────────────────────────────

    def is_blocked(self, hostname: str) -> bool:
        """Check whether a hostname (or any of its parent domains) is blocked."""
        hostname = hostname.lower().strip(".")
        if not hostname:
            return False

        cached = self._cache.get(hostname)
        if cached is not None:
            return cached

        # Build all domain levels to check
        parts = hostname.split(".")
        reversed_candidates = []
        for i in range(len(parts)):
            sub = ".".join(parts[i:])
            reversed_candidates.append(_reverse_domain(sub))

        placeholders = ",".join("?" * len(reversed_candidates))
        try:
            cur = self._conn.execute(
                f"""
                SELECT 1 FROM domains d
                JOIN sources s ON d.source = s.name
                WHERE s.enabled = 1
                  AND d.reversed_domain IN ({placeholders})
                LIMIT 1
            """,
                reversed_candidates,
            )

            blocked = cur.fetchone() is not None
        except sqlite3.Error as exc:
            events.log_warn.send("recorder", text=f"Blocklist lookup failed for {hostname}: {exc}")
            events.log_traceback.send("recorder")
            return False

        self._cache.put(hostname, blocked)
        return blocked

    def is_blocked_url(self, url: str) -> bool:
        """Convenience: extract hostname from a URL and check it."""
        domain = _extract_domain(url)
        if not domain:
            return False
        return self.is_blocked(domain)

    # ── Stats ────────────────────────────────────────────────────────

    def total_domains(self) -> int:
        cur = self._conn.execute("SELECT COUNT(*) FROM domains")
        return cur.fetchone()[0]

    def total_enabled_domains(self) -> int:
        cur = self._conn.execute("""
            SELECT COUNT(*) FROM domains d
            JOIN sources s ON d.source = s.name
            WHERE s.enabled = 1
        """)
        return cur.fetchone()[0]

    # ── Lifecycle ────────────────────────────────────────────────────

    def close(self) -> None:
        self._cache.clear()
        if self._conn is not None:
            try:
                self._conn.close()
            except sqlite3.Error as exc:
                events.log_warn.send("recorder", text=f"Error closing blocklist DB: {exc}")
                events.log_traceback.send("recorder")
            finally:
                self._conn = None

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

    def __repr__(self) -> str:
        sources = len(self.list_sources())
        total = self.total_domains()
        enabled = self.total_enabled_domains()
        return f"<BlocklistDB sources={sources} domains={total} enabled={enabled}>"

      """Shared CDP helpers — timestamp calibration and header reconciliation."""

import time
from datetime import UTC, datetime

class TimestampConverter:
    """Converts CDP MonotonicTime to human-readable ISO 8601 timestamps."""

    def __init__(self):
        self.monotonic_to_wall_offset: float | None = None
        self.offsets_collected = []

    def calibrate(self, monotonic_time: float, wall_time: float) -> None:
        if len(self.offsets_collected) >= 5:
            return
        offset = wall_time - monotonic_time
        self.offsets_collected.append(offset)
        self.monotonic_to_wall_offset = sum(self.offsets_collected) / len(self.offsets_collected)

    def to_unix_timestamp(self, monotonic_time: float) -> float:
        if self.monotonic_to_wall_offset is None:
            self.monotonic_to_wall_offset = time.time() - monotonic_time
        return monotonic_time + self.monotonic_to_wall_offset

    def to_iso8601(self, monotonic_time: float) -> str:
        unix_timestamp = self.to_unix_timestamp(monotonic_time)
        dt = datetime.fromtimestamp(unix_timestamp, tz=UTC)
        return dt.isoformat(timespec="milliseconds")

    def current_iso8601(self) -> str:
        return datetime.now(UTC).isoformat(timespec="milliseconds")

def merge_headers(req, extra_headers):
    if not extra_headers:
        return
    if not req["response_data"]:
        req["response_data"] = {
            "status": 0,
            "headers": {},
            "body": None,
            "base64_encoded": False,
            "charset": "utf-8",
        }
    current = req["response_data"]["headers"]
    for k, v in extra_headers.items():
        current[k] = v

      """Serialization & content-detection helpers for workspace compilation."""

import base64
import logging
import re

from ... import config, events

logger = logging.getLogger(__name__)

try:
    from magika import Magika

    magika_detector = Magika()
    MAGIKA_AVAILABLE = True
    events.log_debug.send("recorder", text="Magika AI detector initialized successfully.")
except ImportError:
    magika_detector = None
    MAGIKA_AVAILABLE = False
    events.log_warn.send("recorder", text="Magika not installed. Skipping advanced content type detection.")

WORKSPACE_DIR = str(config.WORKSPACE_DIR)

def sanitize_filename(name: str) -> str:
    name = name.replace("https://", "").replace("http://", "")
    return re.sub(r"[^\w\-\.]", "_", name)[:100]

def make_serializable(obj):
    if isinstance(obj, str | int | float | bool | type(None)):
        return obj
    if isinstance(obj, bytes):
        return ""
    if isinstance(obj, list):
        return [make_serializable(x) for x in obj]
    if isinstance(obj, dict):
        return {k: make_serializable(v) for k, v in obj.items()}
    return str(obj)

def get_header_val(headers, key):
    if not headers:
        return None
    key = key.lower()
    for k, v in headers.items():
        if k.lower() == key:
            return v
    return None

def extract_cookies_sent(item):
    names = set()
    details = item.get("cookies_sent_details", [])
    for ac in details:
        if ac.get("blockedReasons"):
            continue
        cookie = ac.get("cookie") or {}
        name = cookie.get("name")
        if name:
            names.add(name)
    if not names:
        raw = get_header_val(item.get("headers", {}), "cookie")
        if raw:
            for part in raw.split(";"):
                if "=" in part:
                    names.add(part.split("=")[0].strip())
    return sorted(names)

def extract_cookies_set(item):
    names = set()
    resp = item.get("response_data") or {}
    headers = resp.get("headers") or {}
    raw = get_header_val(headers, "set-cookie")
    if raw:
        for line in raw.split("\n"):
            if "=" in line:
                names.add(line.split("=")[0].strip())
    return sorted(list(names))

def detect_content_type(content, is_base64=False):
    if content is None or not MAGIKA_AVAILABLE or magika_detector is None:
        return None
    try:
        if is_base64:
            byte_content = base64.b64decode(content)
        elif isinstance(content, str):
            byte_content = content.encode("utf-8")
        elif isinstance(content, bytes):
            byte_content = content
        else:
            return None
        result = magika_detector.identify_bytes(byte_content)
        return {
            "label": result.output.label,
            "mime_type": result.output.mime_type,
            "extension": result.output.extensions[0] if result.output.extensions else "bin",
            "all_extensions": result.output.extensions,
            "description": result.output.description,
            "confidence": result.score,
            "is_text": result.output.is_text,
            "group": result.output.group,
        }
    except Exception as e:
        events.log_warn.send("recorder", text=f"Magika error: {e}")
        events.log_traceback.send("recorder")
        return {"label": "unknown", "mime_type": "application/octet-stream", "extension": "bin", "error": str(e)}

def save_content(path, content, is_base64=False):
    if content is None:
        return
    mode = "wb"
    if is_base64:
        try:
            data = base64.b64decode(content)
        except Exception as exc:
            events.log_warn.send("recorder", text=f"Base64 decode failed for {path}, saving raw content instead: {exc}")
            events.log_traceback.send("recorder")
            data = str(content).encode("utf-8")
    elif isinstance(content, str):
        data = content.encode("utf-8")
    else:
        data = str(content).encode("utf-8")
    try:
        with open(path, mode) as f:
            f.write(data)
    except OSError as exc:
        events.log_error.send("recorder", text=f"Failed to write content to {path}: {exc}")
        events.log_traceback.send("recorder")

      /**
 * Automatiq Recorder — background service worker.
 *
 * Relays telemetry actions from content scripts to the Python ActionServer.
 *
 * Why a background SW relay? Content scripts share the *page's* origin for
 * network purposes, so a direct `sendBeacon`/`fetch` to http://127.0.0.1 is a
 * public-secure-origin -> private-network request that triggers Chromium's
 * Private Network Access (PNA) permission prompt. The background SW runs under
 * the extension's own origin and, with `host_permissions: ["<all_urls>"]`, is
 * exempt from PNA — so `fetch` to the loopback endpoint never prompts.
 */
importScripts("config.js");

chrome.runtime.onMessage.addListener((msg) => {
    try {
        fetch(AUTOMATIQ_ENDPOINT, {
            method: "POST",
            body: JSON.stringify(msg),
            keepalive: true,
        }).catch(() => {
            /* ActionServer unreachable — swallow to keep SW quiet */
        });
    } catch (e) {
        /* ignore */
    }
    // No `return true`: fire-and-forget so the content-script callback resolves
    // immediately and we don't pin the message channel open.
});

      // Generated at runtime by BrowserAgent with the chosen ActionServer port.
// Placeholder endpoint (port 0) is overwritten before the browser launches.
var AUTOMATIQ_ENDPOINT = "http://127.0.0.1:0/act";

      {
  "manifest_version": 3,
  "name": "AutomatiQ Recorder",
  "version": "1.0.0",
  "description": "AutomatiQ telemetry capture and visual recording overlay.",
  "background": {
    "service_worker": "background.js"
  },
  "content_scripts": [
    {
      "matches": ["<all_urls>"],
      "all_frames": true,
      "run_at": "document_start",
      "js": ["config.js", "telemetry.js", "visuals.js"]
    }
  ],
  "host_permissions": ["<all_urls>"]
}

      /**
 * Automatiq Telemetry Script
 * Captures clicks, typing, navigation, and generates Chromium DevTools-grade locators.
 */
(function () {
    if (window._automatiqTelemetryLoaded) return;
    window._automatiqTelemetryLoaded = true;

    const _originalConsole = { ...console };
    for (const key in console) {
        if (typeof console[key] === "function") {
            console[key] = function (...args) {
                for (const arg of args) {
                    if (arg instanceof Error) return;
                }
                return _originalConsole[key].apply(this, args);
            };
        }
    }

    const isIframe = window !== window.top;

    // Relay telemetry to the Python ActionServer via the extension's
    // background service worker. A content script shares the *page's* origin
    // for network purposes, so a direct sendBeacon/fetch to http://127.0.0.1
    // is a public->private request that triggers Chromium's Private Network
    // Access permission prompt. The background SW runs under the extension's
    // own origin (with host_permissions) and is exempt from PNA, so it can
    // fetch the loopback endpoint without any prompt.
    function emitAction(payload) {
        payload.url = window.location.href;
        payload.title = document.title;
        payload.is_iframe = isIframe;
        try {
            // Fire-and-forget: the callback exists only to swallow
            // runtime.lastError (e.g. when the SW is mid-wake-up) so Chrome
            // doesn't log an "unchecked runtime.lastError" warning.
            chrome.runtime.sendMessage(payload, () => { void chrome.runtime.lastError; });
        } catch (e) { /* SW not ready / page tearing down — ignore */ }
    }

    emitAction({ type: 'script_loaded', text: 'Telemetry script initialized' });

    // =====================================================================
    // 1. SHARED UTILITIES & SELECTOR GENERATORS (Chromium DevTools Port)
    // =====================================================================
    class SelectorPart {
        constructor(value, optimized) {
            this.value = value;
            this.optimized = optimized || false;
        }
        toString() { return this.value; }
    }

    const findMinMax = ([min, max], fns) => {
        fns.self = fns.self || ((i) => i);
        let index = fns.inc(min), value, isMax;
        do {
            value = fns.valueOf(min);
            isMax = true;
            while (index !== max) {
                min = fns.self(index);
                index = fns.inc(min);
                if (!fns.gte(value, index)) { isMax = false; break; }
            }
        } while (!isMax);
        return value;
    };

    // CSS Selector Generator
    const idSelector = (id) => `#${CSS.escape(id)}`;
    const attributeSelector = (name, value) => `[${name}='${CSS.escape(value)}']`;
    const classSelector = (selector, className) => `${selector}.${CSS.escape(className)}`;
    const nthTypeSelector = (selector, index) => `${selector}:nth-of-type(${index + 1})`;
    const typeSelector = (selector, type) => `${selector}${attributeSelector('type', type)}`;

    const hasUniqueId = (node) => {
        try { return Boolean(node.id) && (node.getRootNode().querySelectorAll(idSelector(node.id)).length === 1); }
        catch (e) { return false; }
    };
    const isUniqueAmongTagNames = (node, children) => {
        for (const child of children) { if (child !== node && child.tagName === node.tagName) return false; }
        return true;
    };
    const isUniqueAmongInputTypes = (node, children) => {
        for (const child of children) { if (child !== node && child.tagName === 'INPUT' && child.type === node.type) return false; }
        return true;
    };
    const getUniqueClassName = (node, children) => {
        const classNames = new Set(node.classList);
        for (const child of children) {
            if (child !== node) {
                for (const className of child.classList) classNames.delete(className);
                if (classNames.size === 0) break;
            }
        }
        if (classNames.size > 0) return classNames.values().next().value;
        return undefined;
    };
    const getTypeIndex = (node, children) => {
        let nthTypeIndex = 0;
        for (const child of children) {
            if (child === node) return nthTypeIndex;
            if (child.tagName === node.tagName) ++nthTypeIndex;
        }
        return 0;
    };

    const getCssSelectorPart = (node, attributes = []) => {
        if (node.nodeType !== Node.ELEMENT_NODE) return;
        for (const attribute of attributes) {
            const value = node.getAttribute(attribute);
            if (value) return new SelectorPart(attributeSelector(attribute, value), true);
        }
        if (hasUniqueId(node)) return new SelectorPart(idSelector(node.id), true);
        const selector = node.tagName.toLowerCase();
        if (['body', 'head', 'html'].includes(selector)) return new SelectorPart(selector, true);
        const parent = node.parentNode;
        if (!parent) return new SelectorPart(selector, true);
        const children = parent.children;
        if (isUniqueAmongTagNames(node, children)) return new SelectorPart(selector, true);
        if (node.tagName === 'INPUT' && isUniqueAmongInputTypes(node, children)) return new SelectorPart(typeSelector(selector, node.type), true);
        const className = getUniqueClassName(node, children);
        if (className !== undefined) return new SelectorPart(classSelector(selector, className), true);
        return new SelectorPart(nthTypeSelector(selector, getTypeIndex(node, children)), false);
    };

    class SelectorRangeOps {
        constructor(attributes = []) { this.buffer = [[]]; this.attributes = attributes; this.depth = 0; }
        inc(node) { return node.parentNode || node.getRootNode(); }
        valueOf(node) {
            const part = getCssSelectorPart(node, this.attributes);
            if (!part) throw new Error('Node is not an element');
            if (this.depth > 1) { this.buffer.unshift([part]); } else { this.buffer[0].unshift(part); }
            this.depth = 0;
            return this.buffer.map(parts => parts.join(' > ')).join(' ');
        }
        gte(selector, node) {
            ++this.depth;
            try { return node.querySelectorAll(selector).length === 1; } catch (e) { return false; }
        }
    }

    const computeCSSSelector = (node, attributes = []) => {
        const selectors = [];
        try {
            let root;
            while (node && node.nodeType === Node.ELEMENT_NODE) {
                root = node.getRootNode();
                selectors.unshift(findMinMax([node, root], new SelectorRangeOps(attributes)));
                node = root.host ? root.host : root;
            }
        } catch (e) { return undefined; }
        return selectors;
    };

    // ARIA Selector Generator
    const browserA11yBindings = {
        getAccessibleName: (node) => node.getAttribute('aria-label') || node.getAttribute('alt') || node.title || node.innerText || '',
        getAccessibleRole: (node) => node.getAttribute('role') || node.localName || ''
    };

    class ARIASelectorComputer {
        constructor(bindings) { this.bindings = bindings; }
        computeUniqueARIASelectorForElements(elements, queryByRoleOnly) {
            const selectors = [];
            let parent = document;
            for (const element of elements) {
                let result = this.queryA11yTreeOneByName(parent, element.name);
                if (result) { selectors.push(element.name); parent = result; continue; }
                if (queryByRoleOnly) {
                    result = this.queryA11yTreeOneByRole(parent, element.role);
                    if (result) { selectors.push(`[role="${element.role}"]`); parent = result; continue; }
                }
                result = this.queryA11yTreeOneByNameAndRole(parent, element.name, element.role);
                if (result) { selectors.push(`${element.name}[role="${element.role}"]`); parent = result; continue; }
                return;
            }
            return selectors;
        }
        queryA11yTreeOneByName(parent, name) {
            if (!name) return null;
            const result = this.queryA11yTree(parent, name, undefined, 2);
            return result.length === 1 ? result[0] : null;
        }
        queryA11yTreeOneByRole(parent, role) {
            if (!role) return null;
            const result = this.queryA11yTree(parent, undefined, role, 2);
            return result.length === 1 ? result[0] : null;
        }
        queryA11yTreeOneByNameAndRole(parent, name, role) {
            if (!role || !name) return null;
            const result = this.queryA11yTree(parent, name, role, 2);
            return result.length === 1 ? result[0] : null;
        }
        queryA11yTree(parent, name, role, maxResults = 0) {
            const result = [];
            if (!name && !role) return result;
            const shouldMatchName = Boolean(name);
            const shouldMatchRole = Boolean(role);
            const collect = (root) => {
                const iter = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);
                do {
                    const currentNode = iter.currentNode;
                    if (!currentNode || currentNode.nodeType !== Node.ELEMENT_NODE) continue;
                    if (currentNode.shadowRoot) collect(currentNode.shadowRoot);
                    if (currentNode instanceof ShadowRoot) continue;
                    if (shouldMatchName && this.bindings.getAccessibleName(currentNode) !== name) continue;
                    if (shouldMatchRole && this.bindings.getAccessibleRole(currentNode) !== role) continue;
                    result.push(currentNode);
                    if (maxResults && result.length >= maxResults) return;
                } while (iter.nextNode());
            };
            collect(parent.nodeType === Node.DOCUMENT_NODE ? document.documentElement : parent);
            return result;
        }
        compute(node) {
            let selector, current = node;
            const elements = [];
            while (current) {
                const role = this.bindings.getAccessibleRole(current);
                const name = this.bindings.getAccessibleName(current);
                if (!role && !name) { if (current === node) break; }
                else {
                    elements.unshift({ name, role });
                    selector = this.computeUniqueARIASelectorForElements(elements, current !== node);
                    if (selector) break;
                    if (current !== node) elements.shift();
                }
                current = current.parentNode;
                if (current instanceof ShadowRoot) current = current.host;
            }
            return selector;
        }
    }

    const computeARIASelector = (node) => {
        try { return new ARIASelectorComputer(browserA11yBindings).compute(node); }
        catch (e) { return undefined; }
    };

    // Text Selector Generator
    const textQuerySelectorAll = function*(root, text) {
        const xpath = `//text()[contains(., ${JSON.stringify(text)})]/parent::*`;
        try {
            const snapshot = document.evaluate(xpath, root, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
            for (let i = 0; i < snapshot.snapshotLength; i++) yield snapshot.snapshotItem(i);
        } catch (e) {}
    };

    const computeTextSelector = (node) => {
        const content = (node.innerText || node.textContent || '').trim();
        if (!content) return;
        if (content.length <= 12) {
            const elements = [];
            for (const value of textQuerySelectorAll(document, content)) { elements.push(value); if (elements.length >= 2) break; }
            return elements.length === 1 && elements[0] === node ? [content] : undefined;
        }
        if (content.length > 64) return;
        let left = 12, right = content.length;
        while (left <= right) {
            const center = left + ((right - left) >> 2);
            const elements = [];
            for (const value of textQuerySelectorAll(document, content.slice(0, center))) { elements.push(value); if (elements.length >= 2) break; }
            if (elements.length !== 1 || elements[0] !== node) { left = center + 1; } else { right = center - 1; }
        }
        if (right === content.length) return;
        const length = right + 1;
        const remainder = content.slice(length, length + 64);
        const match = remainder.search(/ |$/);
        return [content.slice(0, length + (match > -1 ? match : 0))];
    };

    // =====================================================================
    // 2. AUTOMATIQ RECORDING LOGIC
    // =====================================================================

    // 1. Track Every Keypress (Restored)
    document.addEventListener('keydown', (e) => {
        if (['Shift', 'Control', 'Alt', 'Meta'].includes(e.key)) return;
        const target = (e.composedPath && e.composedPath()[0]) || e.target;
        emitAction({
            type: 'keypress',
            key: e.key,
            code: e.code,
            tag: target.tagName,
            value: target.value || ''
        });
    }, true);

    // 2. Track Input Changes (Restored)
    document.addEventListener('change', (e) => {
        if (['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)) {
            emitAction({
                type: 'input',
                tag: e.target.tagName,
                name: e.target.name || e.target.id || '',
                value: e.target.value
            });
        }
    }, true);

    // 3. Track Clicks (Upgraded with Locators & Delay)
    document.addEventListener('mousedown', (e) => {
        // composedPath()[0] pierces shadow DOM to get the real clicked element
        const rawTarget = (e.composedPath && e.composedPath()[0]) || e.target;
        if (!(rawTarget instanceof Element)) return;

        // Try to find the best interactive ancestor for locator quality,
        // but ALWAYS fall back to rawTarget — never silently drop the click
        const interactiveSelector = `button, a, input, select, textarea, label, [role], [tabindex]:not([tabindex="-1"]), [onclick]`;
        const target = rawTarget.closest(interactiveSelector) || rawTarget;

        // Compute strict DOM coordinates immediately
        const cssPath = computeCSSSelector(target);
        const ariaPath = computeARIASelector(target);
        const textPath = computeTextSelector(target);

        // Wait 50ms for React/Vue/Google Forms to update visually before reading attributes
        setTimeout(() => {
            emitAction({
                type: 'click',
                tag: target.tagName,
                text: (target.innerText || target.value || '').substring(0, 100).trim(),
                id: target.id || '',
                href: target.href || '',
                role: target.getAttribute('role') || '',
                ariaLabel: target.getAttribute('aria-label') || '',
                ariaChecked: target.getAttribute('aria-checked') || '',
                dataValue: target.dataset?.value || '',
                inputType: target.type || '',
                locators: {
                    css: cssPath ? cssPath.join(' > ') : null,
                    aria: ariaPath ? ariaPath.join(' > ') : null,
                    text: textPath ? textPath[0] : null
                }
            });
        }, 50);
    }, true);

    // 4. Track Page Changes (SPA & Hash changes) (Restored)
    let lastUrl = location.href;
    new MutationObserver(() => {
        if (location.href !== lastUrl) {
            lastUrl = location.href;
            emitAction({ type: 'page_changed', newUrl: location.href, reason: 'mutation' });
        }
    }).observe(document, { subtree: true, childList: true });

    window.addEventListener('popstate', () => {
        lastUrl = location.href;
        emitAction({ type: 'page_changed', newUrl: location.href, reason: 'popstate' });
    });

    window.addEventListener('hashchange', () => {
        lastUrl = location.href;
        emitAction({ type: 'page_changed', newUrl: location.href, reason: 'hashchange' });
    });

    // Popups opened via window.open are detected on the Python side through
    // CDP TargetCreated events, so no JS hook is needed here (and an isolated
    // content script cannot override the page's main-world window.open anyway).

})();
